/* Earth textures — NASA Blue Marble / Earth at Night (public domain),
   resampled and inlined so the scene renders offline without CORS issues. */
const EARTH_TEX = {
  day: "data:image/jpeg;base64,",
  night: "data:image/jpeg;base64,",
  galaxy: "data:image/jpeg;base64,",
  cloud: "data:image/jpeg;base64,"
};

/* keep the global for the WebGL module, and expose it as an ES module */
window.EARTH_TEX = EARTH_TEX
export default EARTH_TEX
